namespace AeroScience.Shared;

// Versioned derived views, never a new scientific archive or an authorization to upload.
public enum CampaignWorkState { NotStarted, Available, ClaimedInProgress, EvidenceReceived, AwaitingReview, MoreEvidenceNeeded, PartiallyFulfilled, CompletedByApprovedEvidence }
public sealed record CampaignProgressTotals(long PublishedCards,long CompletedCards,long RequiredPilotContributions,long ApprovedPilotContributions,long ReceivedCards,long AwaitingReview,long MoreEvidenceNeeded,long Rejected,long PartiallyReviewed,long UnavailableCards,long ReceivedPackages=0,long UnavailableReviews=0);
public sealed record CampaignProgressView(int Version,Guid OrganizationId,Guid ProgramId,string ProgramName,Guid CampaignId,int CampaignRevision,string Name,string Objective,DateTimeOffset AsOfUtc,CampaignProgressTotals Totals,bool CanReview,bool CanManage,string CountingRule,string PrivacyPolicy);
public sealed record ProgramProgressView(int Version,Guid OrganizationId,Guid ProgramId,string Name,string Description,DateTimeOffset AsOfUtc,OrganizationPage<CampaignProgressView> Campaigns);
public sealed record CampaignCardProgress(Guid OpportunityId,int PublicationRevision,string PublicationSha256,int CampaignRevision,string Name,string Description,string Objective,int RequiredDistinctPilots,long ApprovedDistinctPilots,int ActiveClaims,int ReservedClaims,int AvailableClaims,bool Unavailable,long ReceivedCards,long AwaitingReview,long MoreEvidenceNeeded,long Rejected,long PartiallyReviewed,int RequiredFindings,long ApprovedRequirementFindings,DateTimeOffset? LastAcceptedUtc,CampaignWorkState State,string NextAction,int AcceptancePolicyVersion=1);
public sealed record CampaignCardVersion(int PublicationRevision,string PublicationSha256,bool Current,long ApprovedIndependentPilots);
public sealed record CampaignCardDetail(CampaignProgressView Campaign,CampaignCardProgress Card,OrganizationPage<CampaignCardVersion> Versions);
public sealed record ApprovedOutcomeCount(ResearchAttemptOutcome Outcome,long Count,string Meaning);
public sealed record ApprovedRequirementSummary(string Key,string Name,string Objective,string Criteria,Guid ReviewEventId,int ReviewPolicyVersion,DateTimeOffset ApprovedUtc,Guid[] ReceivedReferences,ApprovedOutcomeCount[] OriginalOutcomes,string[] Limitations);
public sealed record ApprovedResearchSummary(int Version,Guid RootReceiptId,Guid CardId,Guid OpportunityId,int PublicationRevision,string PublicationSha256,string DefinitionSha256,Guid CampaignId,string CampaignName,string CardName,string Objective,string Contributor,DateTimeOffset AcceptedUtc,int AcceptancePolicyVersion,ApprovedRequirementSummary[] Requirements,string[] Limitations,bool IsOwnContribution=false);
public sealed record ApprovedMeasurementSummary(string GroupId,string RequirementKey,string Measurement,string Unit,string Instrument,string Provenance,string SourceCategory,string SourceIdentitySha256,string FlightReference,DateTimeOffset StartUtc,DateTimeOffset EndUtc,long Count,double? Minimum,double? Maximum,double? MinimumAltitudeFeetMsl,double? MaximumAltitudeFeetMsl,long LocatedReadings,string Quality);
