public sealed record CampaignOwnWork(Guid OpportunityId,int PublicationRevision,string Name,OrganizationClaimState ClaimState,long ReceivedCards,long ApprovedCards,long EvidenceRequests,string NextAction);
public sealed record CampaignReviewAttention(Guid RootReceiptId,Guid CardId,string CardName,ResearchReviewState State,int ApprovedFindings,int RequiredFindings,DateTimeOffset UpdatedUtc);
public sealed record OrganizationProgressResponse<T>(string Status,bool VerifiedNow,DateTimeOffset? CheckedUtc,T? Value);
